{
  "originalFormula": "E_{F} = E_{c} - 0.2982 \, eV",
  "genericFormula": "E_{F} = E_{c} - E_{0}",
  "description": "Esta fórmula representa a relação entre a energia do nível de Fermi e a energia da borda da banda de condução em um material semicondutor. O nível de Fermi é uma medida da energia dos elétrons em um sistema à temperatura zero, enquanto a energia da borda da banda de condução é a energia mínima necessária para que um elétron possa se mover livremente e contribuir para a condução elétrica. O valor subtraído indica uma diferença de energia que pode ser influenciada por fatores como dopagem ou temperatura.",
  "concepts": [
    "Nível de Fermi",
    "Energia da borda da banda de condução",
    "Semicondutores",
    "Dopagem",
    "Condução elétrica"
  ],
  "symbols": [
    {
      "symbol": "E_{F}",
      "description": "Representa a energia do nível de Fermi, que indica a máxima energia que os elétrons podem ter a temperatura zero."
    },
    {
      "symbol": "E_{c}",
      "description": "Representa a energia da borda da banda de condução, que é a energia mínima necessária para que um elétron se mova livremente no material."
    },
    {
      "symbol": "0.2982 \, eV",
      "description": "Representa uma diferença de energia específica, que pode ser vista como uma quantidade de energia que deve ser subtraída da energia da borda da banda de condução para encontrar o nível de Fermi."
    }
  ]
}

{
  "originalFormula": "E_{F} = E_{v} + 0.179 \, eV",
  "genericFormula": "E_{F} = E_{v} + C",
  "description": "Esta fórmula representa a relação entre a energia do nível de Fermi e a energia do nível de valência em um material semicondutor. O nível de Fermi é uma medida da energia máxima ocupada por elétrons em um sistema a temperatura zero, enquanto o nível de valência é a energia dos elétrons que estão ligados aos átomos do material. A diferença entre esses dois níveis é uma constante que representa a energia necessária para mover um elétron do nível de valência para o nível de Fermi.",
  "concepts": [
    "Nível de Fermi",
    "Nível de Valência",
    "Energia de Bandas",
    "Semicondutores"
  ],
  "symbols": [
    {
      "symbol": "E_{F}",
      "description": "Representa a energia do nível de Fermi, que é a energia máxima ocupada por elétrons em um material a temperatura zero."
    },
    {
      "symbol": "E_{v}",
      "description": "Representa a energia do nível de valência, que é a energia dos elétrons que estão ligados aos átomos do material."
    },
    {
      "symbol": "C",
      "description": "Representa uma constante que indica a diferença de energia entre o nível de valência e o nível de Fermi, neste caso, uma energia de 0.179 electronvolts."
    }
  ]
}
